arguments.command:
set -euo pipefail; export DRIVE_SESSION_TAG="nothingness_linux_debug"; export DRIVE_TARGET=linux; export DRIVE_RUN_LOG="/tmp/flutter_run_${DRIVE_SESSION_TAG}.log"; export DRIVE_FLUTTER_FIFO="/tmp/flutter_input_${DRIVE_SESSION_TAG}"; export DRIVE_DESKTOP_HOME="/tmp/nothingness_${DRIVE_SESSION_TAG}"; D=.claude/skills/agent-emulator-debugging/scripts/drive.py;

get(){ $D inspect | python3 -c "import sys,json; j=json.load(sys.stdin); p=j['playback']; si=p.get('songInfo') or {}; print('isPlaying',p['isPlaying'],'currentIndex',p['currentIndex'],'queueLength',p['queueLength'],'title',si.get('title'),'posMs',si.get('position'),'durMs',si.get('duration'))"; }

echo '--- pause check'; $D pause >/dev/null; get;
echo '--- resume check'; $D resume >/dev/null; get;
echo '--- next check'; $D next >/dev/null; get;
echo '--- seek check'; $D seek 1:00 >/dev/null; get;

